using Godot;
using System;
using System.Linq;
using Settings=Godot.Collections.Dictionary;

public partial class EnvironmentScatterInspector : RefCounted
{
    private readonly EnvironmentDocumentOperations _documents=new();
    private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    private static RefCounted Session(Control owner)=>owner.Get("session").As<RefCounted>();
    private static VBoxContainer Panel(Control owner)=>owner.Get("properties").As<VBoxContainer>();
    private static void Heading(Node parent,string title){var label=new Label {Text=title};label.AddThemeColorOverride("font_color",new Color("7edbc4"));parent.AddChild(label);}
    private static void Button(Node parent,string title,Action action){var button=new Button {Text=title};parent.AddChild(button);button.Pressed+=action;}
    private static void Number(Node parent,string title,double value,double low,double high,double step,Action<double> write)
    {var row=new HBoxContainer();parent.AddChild(row);row.AddChild(new Label {Text=title,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});var number=new DragNumber();number.MinValue=low;number.MaxValue=high;number.Step=step;number.CustomMinimumSize=new Vector2(85,0);number.SetValueNoSignal(value);row.AddChild(number);number.ValueChanged+=write.Invoke;number.Connect("drag_committed",Callable.From<double>(write));}
    private static void Toggle(Node parent,string title,bool value,Action<bool> write){var button=new CheckButton {Text=title,ButtonPressed=value};parent.AddChild(button);button.Toggled+=enabled=>write(enabled);}
    private static void Choice(Node parent,string[] values,int selected,Action<int> write){var choice=new OptionButton();parent.AddChild(choice);foreach(string value in values)choice.AddItem(value);choice.Select(selected);choice.ItemSelected+=index=>write((int)index);}
    private static void Edit(Control owner,Resource scatter,string label,Action change)
    {
        if(!GodotObject.IsInstanceValid(owner)||!owner.IsInsideTree())return;var session=Session(owner);bool current=false;foreach(var value in session.Get("document").As<Resource>().Get("component_settings").AsGodotDictionary().Values){var settings=value.AsGodotDictionary();if(Get(settings,"scatter").As<Resource>()==scatter){current=true;break;}}if(!current)return;session.Call("begin");change();session.Call("commit",label);
    }
    public void set_biome(Control owner,Resource scatter,string id,bool enabled)
    {Edit(owner,scatter,"Change scatter biome filter",()=>{var ids=scatter.Get("biome_ids").AsStringArray().ToList();if(enabled&&!ids.Contains(id))ids.Add(id);else if(!enabled)ids.Remove(id);scatter.Set("biome_ids",ids.ToArray());});}
    public void properties(Control owner,Resource item,Resource scatter)
    {
        string id=item.Get("id").AsString();var parent=Panel(owner);var session=Session(owner);var canvas=owner.Get("canvas").As<Control>();Heading(parent,"Scatter rules");var ground=_documents.terrain(session.Get("document").As<Resource>(),scatter.Get("terrain_id").AsString());var biomes=ground?.Get("biomes").As<Resource>();
        if(biomes!=null){Heading(parent,"Suitable biomes");foreach(var value in biomes.Get("definitions").AsGodotArray()){var definition=value.AsGodotDictionary();string biome=definition["id"].AsString();var toggle=new CheckBox {Text=Get(definition,"name","Biome").AsString(),ButtonPressed=scatter.Get("biome_ids").AsStringArray().Contains(biome)};parent.AddChild(toggle);toggle.Toggled+=enabled=>set_biome(owner,scatter,biome,enabled);}}
        void Fields((string Title,string Key,double Low,double High,double Step)[] specs,string label){foreach(var spec in specs)Number(parent,spec.Title,scatter.Get(spec.Key).AsDouble(),spec.Low,spec.High,spec.Step,value=>Edit(owner,scatter,label,()=>scatter.Set(spec.Key,spec.Key is "seed" or "budget" or "cluster_count"?Variant.From((long)value):Variant.From(value))));}
        Fields(new[]{("Density / m²","density",0.0,100.0,.01),("Minimum spacing (m)","minimum_distance",.001,100.0,.05),("Seed","seed",-100000.0,100000.0,1.0),("Instance budget","budget",1.0,20000.0,1.0)},"Change scatter rules");
        Fields(new[]{("Render cluster size (0 = one batch)","render_cluster_size",0.0,4096.0,8.0),("Render distance (0 = all)","render_distance",0.0,100000.0,10.0),("Detail bias","lod_bias",.05,16.0,.05)},"Change scatter rendering");
        Toggle(parent,"Automatic mesh detail",scatter.Get("lod_enabled").AsBool(),value=>Edit(owner,scatter,"Change scatter mesh detail",()=>scatter.Set("lod_enabled",value)));Toggle(parent,"Stream nearby instance clusters",scatter.Get("stream_instances").AsBool(),value=>Edit(owner,scatter,"Change instance streaming",()=>scatter.Set("stream_instances",value)));
        Button(parent,"Regenerate",()=>{canvas.Get("renderer").As<Node3D>().Get("signatures").AsGodotDictionary().Remove(id);canvas.Call("request_sync");});Choice(parent,new[]{"Terrain surface","Cave floors","Cave ceilings","Cave walls"},scatter.Get("surface_domain").AsInt32(),value=>Edit(owner,scatter,"Change scatter surface",()=>scatter.Set("surface_domain",value)));
        if(scatter.Get("use_anchors").AsBool())Choice(parent,new[]{"Anchor on terrain","Anchor offset from terrain","Authored anchor elevation"},scatter.Get("anchor_height_mode").AsInt32(),value=>Edit(owner,scatter,"Change anchor height mode",()=>scatter.Set("anchor_height_mode",value)));
        Fields(new[]{("Cluster centers","cluster_count",0.0,4096.0,1.0),("Cluster radius (m)","cluster_radius",.01,1000.0,.1)},"Change scatter clusters");
        void Range(string title,string key,int axis,double low,double high,double step,string label)
        {Vector2 Read()=>key=="region_position"?scatter.Get("region").AsRect2().Position:key=="region_size"?scatter.Get("region").AsRect2().Size:scatter.Get(key).AsVector2();Number(parent,title,Read()[axis],low,high,step,value=>Edit(owner,scatter,label,()=>{var vector=Read();vector[axis]=(float)value;if(key is "region_position" or "region_size"){var rect=scatter.Get("region").AsRect2();if(key=="region_position")rect.Position=vector;else rect.Size=vector;scatter.Set("region",rect);}else scatter.Set(key,vector);}));}
        foreach(var spec in new[]{("Temperature","temperature_range",-100.0,100.0),("Humidity","humidity_range",0.0,1.0),("Shore distance","shore_range",0.0,1000000.0),("Water depth","water_depth_range",0.0,10000.0)})for(int axis=0;axis<2;axis++)Range(spec.Item1+(axis==0?" min":" max"),spec.Item2,axis,spec.Item3,spec.Item4,.1,"Change ecological range");
        instances(owner,item,scatter);var painting=new HBoxContainer();parent.AddChild(painting);foreach(string mode in new[]{"Paint scatter","Erase scatter"})Button(painting,mode.Split(' ')[0],()=>{canvas.Set("environment_tool",mode);owner.Call("_refresh_context");canvas.GrabFocus();});Button(parent,"Clear painted regions",()=>Edit(owner,scatter,"Clear scatter regions",()=>{scatter.Get("paint_regions").AsGodotArray().Clear();scatter.Get("erase_regions").AsGodotArray().Clear();}));
        foreach(var spec in new[]{("Scale","scale_range",.01,100.0,.01),("Yaw","yaw_range",-360.0,360.0,1.0),("Elevation","height_range",-10000.0,10000.0,.1),("Slope","slope_range",0.0,90.0,1.0)})for(int axis=0;axis<2;axis++)Range(spec.Item1+(axis==0?" min":" max"),spec.Item2,axis,spec.Item3,spec.Item4,spec.Item5,"Change scatter range");
        foreach(var spec in new[]{("Region X","region_position",0,-10000.0,10000.0),("Region Z","region_position",1,-10000.0,10000.0),("Region width","region_size",0,.1,10000.0),("Region length","region_size",1,.1,10000.0)})Range(spec.Item1,spec.Item2,spec.Item3,spec.Item4,spec.Item5,.1,"Change scatter range");
        Toggle(parent,"Follow surface normal",scatter.Get("align_normal").AsBool(),value=>Edit(owner,scatter,"Align scatter",()=>scatter.Set("align_normal",value)));Toggle(parent,"Object collisions",scatter.Get("collisions").AsBool(),value=>Edit(owner,scatter,"Toggle scatter collision",()=>scatter.Set("collisions",value)));
        Heading(parent,"Weighted asset palette");var palette=scatter.Get("palette").AsGodotArray();for(int index=0;index<palette.Count;index++){int slot=index;var entry=palette[index].AsGodotDictionary();var row=new HBoxContainer();parent.AddChild(row);var source=entry["source"];string title=source.VariantType==Variant.Type.Object?"Model":source.AsString().GetFile();if(source.VariantType==Variant.Type.Object&&source.As<Resource>() is Resource resource&&resource.HasMethod("component")){var components=resource.Get("components").AsGodotArray();if(components.Count>0)title=components[0].As<Resource>().Get("title").AsString();}row.AddChild(new Label {Text=title,TooltipText=source.VariantType==Variant.Type.Object?title:source.AsString(),TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});Number(parent,"Weight",Get(entry,"weight",1.0).AsDouble(),0,100,.1,value=>Edit(owner,scatter,"Change scatter weight",()=>scatter.Get("palette").AsGodotArray()[slot].AsGodotDictionary()["weight"]=value));Button(row,"×",()=>Edit(owner,scatter,"Remove scatter source",()=>scatter.Get("palette").AsGodotArray().RemoveAt(slot)));}
        Button(parent,"Add palette model…",()=>owner.Call("_add_palette_asset",id));
    }
    public void instances(Control owner,Resource item,Resource scatter)
    {
        var nodes=owner.Get("canvas").As<Control>().Get("renderer").As<Node3D>().Get("nodes").AsGodotDictionary();string itemId=item.Get("id").AsString();if(!nodes.TryGetValue(itemId,out var value))return;var node=value.As<Node>();if(!GodotObject.IsInstanceValid(node))return;var result=node.GetMeta("scatter_result",new Settings()).AsGodotDictionary();var placements=Get(result,"placements",new Settings()).AsGodotDictionary();var parent=Panel(owner);string warning=Get(result,"warning","").AsString();if(warning.Length>0)parent.AddChild(new Label {Text=warning,AutowrapMode=TextServer.AutowrapMode.WordSmart});if(placements.Count==0)return;Heading(parent,"Individual instances");var picker=new OptionButton {FitToLongestItem=false,TooltipText="Stable candidate identities; up to the first 1000 instances."};parent.AddChild(picker);var identities=placements.Keys.Take(1000).Select(id=>id.AsString()).ToArray();foreach(string id in identities)picker.AddItem(id);var row=new HBoxContainer();parent.AddChild(row);Button(row,"Remove",()=>Edit(owner,scatter,"Remove scatter instance",()=>scatter.Get("overrides").AsGodotDictionary()[identities[picker.Selected]]=new Settings {["deleted"]=true}));Button(row,"Make editable",()=>{string id=identities[picker.Selected];owner.Get("status").As<Label>().Text=Session(owner).Call("promote_scatter",itemId,id,placements[id]).AsString();});Button(parent,"Reset instance overrides",()=>Edit(owner,scatter,"Reset scatter overrides",()=>scatter.Get("overrides").AsGodotDictionary().Clear()));
    }
}
